import urllib.request
import re

req = urllib.request.Request('https://proceedings.neurips.cc/paper_files/paper/2024', headers={'User-Agent': 'Mozilla/5.0'})
html = urllib.request.urlopen(req, timeout=30).read().decode('utf-8')

# Extract paper entries
# Each paper is in <li class="..." data-track="...">
# with <div class="paper-content"> containing <a> title and <a> PDF
# Let's find paper blocks
import html.parser

class PaperParser(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.papers = []
        self.current_paper = {}
        self.in_paper = False
        self.in_li = False
        self.in_paper_content = False
        self.in_title = False
        self.in_pdf = False
        self.current_text = ''
        self.in_div = False
        self.div_class = ''

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        if tag == 'li' and 'paper-list' in self.get_parent_html('ul'):
            self.in_li = True
            self.current_paper = {'track': attrs_dict.get('data-track', '')}
        elif tag == 'div' and 'paper-content' in attrs_dict.get('class', ''):
            self.in_paper_content = True
        elif tag == 'a' and self.in_paper_content:
            href = attrs_dict.get('href', '')
            title_text = attrs_dict.get('title', '')
            if title_text:
                self.current_paper['title'] = title_text
            if href and href.endswith('.pdf'):
                self.current_paper['pdf'] = href
            if href and 'hash/' in href:
                self.current_paper['paper_link'] = href
            self.in_title = True
        elif tag == 'span' and 'track-type' in attrs_dict.get('class', ''):
            self.current_paper['track_type'] = attrs_dict.get('class', '').replace('track-type', '').strip()

    def handle_endtag(self, tag):
        if tag == 'li' and self.in_li:
            if self.current_paper:
                self.papers.append(self.current_paper)
            self.in_li = False
            self.current_paper = {}
        elif tag == 'a' and self.in_title:
            self.in_title = False

parser = PaperParser()
parser.feed(html)
print(f'Found {len(parser.papers)} papers')
print(f'First paper: {parser.papers[0] if parser.papers else "None"}')
print(f'Sample: {parser.papers[1] if len(parser.papers) > 1 else "None"}')
